import random, sys, json
sys.path.insert(0,'/app')
from language import validate, InvalidProgram
from checker import check, StaticError
from interpreter import run

KINDS=['int','text','bool','unit']
LIT={'int':lambda r: r.randint(-3,3),
     'text':lambda r: r.choice(['a','b','hi']),
     'bool':lambda r: r.choice([True,False]),
     'unit':lambda r: None}

class G:
    def __init__(self,rng):
        self.r=rng
        self.counter=0
        self.cells={}     # name -> declared frozenset
        self.cellinit={}
        self.vars={}      # name -> type (frozenset scalar kinds, or ('fn',T))
        self.inputs={}
        self.nodes=0
    def nm(self,p):
        self.counter+=1
        return '%s%d'%(p,self.counter)

    # generate expression of exact scalar singleton type {k}
    def escalar(self,k,d):
        r=self.r
        if d>3: return ['lit',LIT[k](r)]
        opts=[('lit',)]
        for n,t in self.vars.items():
            if t==frozenset((k,)): opts.append(('var',n))
        for n,t in self.cells.items():
            if t==frozenset((k,)): opts.append(('get',n))
        if k=='int':
            opts.append(('add',)); opts.append(('lt',))
        if k=='text': opts.append(('cat',))
        if k=='bool': opts.append(('not',)); opts.append(('is',))
        # call of function returning k
        for n,t in self.vars.items():
            if isinstance(t,tuple) and t[0]=='fn' and t[1]==frozenset((k,)):
                opts.append(('callvar',n))
        c=r.choice(opts)
        if c[0]=='lit': return ['lit',LIT[k](r)]
        if c[0]=='var': return ['var',c[1]]
        if c[0]=='get': return ['get',c[1]]
        if c[0]=='add': return ['add',self.escalar('int',d+1),self.escalar('int',d+1)]
        if c[0]=='lt':  return ['lt',self.escalar('int',d+1),self.escalar('int',d+1)]
        if c[0]=='cat': return ['cat',self.escalar('text',d+1),self.escalar('text',d+1)]
        if c[0]=='not': return ['not',self.escalar('bool',d+1)]
        if c[0]=='is':
            n=r.choice(list(self.cells))
            return ['is',n,r.choice(KINDS)]
        if c[0]=='callvar':
            return ['call',['var',c[1]]]
    def efn(self,T,d):
        # fn with result type T (scalar or nested fn)
        body,restype=self.genfnbody(T,d)
        return ['fn',body,restype]
    def genfnbody(self,T,d):
        r=self.r
        saved=dict(self.vars)
        body=[]
        # optionally some statements
        for _ in range(r.randint(0,2)):
            if self.nodes>200: break
            body.append(self.stmt(d+1,inside_fn=True))
        if isinstance(T,frozenset):
            res=self.escalar(list(T)[0],d+1)
        else:
            res=self.efn(T[1],d+1)
        self.vars=saved
        return body,res
    def efnT(self,T,d):
        # expression of type T (which may be ('fn',...))
        r=self.r
        if isinstance(T,frozenset):
            # maybe a call of a fn returning T
            for n,t in self.vars.items():
                if isinstance(t,tuple) and t[1]==T and r.random()<0.3:
                    return ['call',['var',n]]
            return self.escalar(list(T)[0],d)
        else:
            opts=[('fnlit',)]
            for n,t in self.vars.items():
                if t==T: opts.append(('var',n))
            c=r.choice(opts)
            if c[0]=='var': return ['var',c[1]]
            return self.efn(T,d)
    def stmt(self,d,inside_fn=False):
        r=self.r
        if self.nodes>250: return ['eval',['lit',0]]
        self.nodes+=1
        opts=['let','assign','set','eval','if','repeat','letfn']
        if not self.vars: opts=[o for o in opts if o not in ('assign',)]
        if not self.cells: opts=[o for o in opts if o!='set']
        if d>3: opts=[o for o in opts if o not in ('if','repeat','letfn')]
        op=r.choice(opts)
        if op=='let':
            T=r.choice([frozenset((k,)) for k in KINDS])
            n=self.nm('v')
            e=self.efnT(T,d)
            self.vars[n]=T
            return ['let',n,e]
        if op=='letfn':
            # let a variable be a function (maybe nested)
            if r.random()<0.5:
                T=frozenset((r.choice(KINDS),))
            else:
                T=('fn',frozenset((r.choice(KINDS),)))
            n=self.nm('f')
            e=self.efn(T,d)
            self.vars[n]=T
            return ['let',n,e]
        if op=='assign':
            cand=[n for n,t in self.vars.items() if not isinstance(t,tuple)]
            if cand and r.random()<0.7:
                n=r.choice(cand)
                return ['assign',n,self.efnT(self.vars[n],d)]
            # assign a function variable to a fn with same result shape (writes may differ)
            fcand=[n for n,t in self.vars.items() if isinstance(t,tuple)]
            if fcand:
                n=r.choice(fcand)
                return ['assign',n,self.efn(self.vars[n],d)]
            n=r.choice(list(self.vars))
            return ['assign',n,self.efnT(self.vars[n],d)]
        if op=='set':
            n=r.choice(list(self.cells))
            k=r.choice(list(self.cells[n]))
            return ['set',n,self.escalar(k,d)]
        if op=='eval':
            T=r.choice([frozenset((k,)) for k in KINDS]+[(('fn',frozenset(('int',))))])
            e=self.efnT(T,d)
            return ['eval',e]
        if op=='if':
            if self.cells and r.random()<0.6:
                n=r.choice(list(self.cells))
                guard=['is',n,r.choice(list(self.cells[n]))]
            else:
                guard=self.escalar('bool',d)
            tb=self.block(d+1)
            eb=self.block(d+1)
            return ['if',guard,tb,eb]
        if op=='repeat':
            cnt=self.escalar('int',d)
            body=self.block(d+1)
            return ['repeat',cnt,body]
    def block(self,d):
        saved=dict(self.vars)
        body=[]
        for _ in range(self.r.randint(0,3)):
            if self.nodes>250: break
            body.append(self.stmt(d))
        self.vars=saved
        return body

def gen(rng):
    g=G(rng)
    nc=rng.randint(1,2)
    for i in range(nc):
        ks=rng.sample(KINDS,rng.randint(1,2))
        k0=rng.choice(ks)
        name='c%d'%i
        g.cells[name]=frozenset(ks)
        g.cellinit[name]=LIT[k0](rng)
    ni=rng.randint(0,2)
    inputs={}
    for i in range(ni):
        k=rng.choice(KINDS)
        n='i%d'%i
        inputs[n]=LIT[k](rng)
        g.inputs[n]=frozenset((k,))
    g.vars=dict(g.inputs)
    body=g.block(0)
    return {'cells':{n:{'types':sorted(g.cells[n]),'value':g.cellinit[n]} for n in g.cells},
            'inputs':inputs,'body':body}

def main():
    N=int(sys.argv[1]) if len(sys.argv)>1 else 20000
    seed=int(sys.argv[2]) if len(sys.argv)>2 else 1
    rng=random.Random(seed)
    stats={}
    found=[]
    other=[]
    for i in range(N):
        p=gen(rng)
        try: validate(p)
        except InvalidProgram: stats['invalid']=stats.get('invalid',0)+1; continue
        try: check(p)
        except StaticError as e: stats['reject']=stats.get('reject',0)+1; continue
        stats['accept']=stats.get('accept',0)+1
        try:
            res=run(p)
        except Exception as e:
            stats['exc']=stats.get('exc',0)+1
            other.append((json.dumps(p),repr(e)))
            continue
        st=res['status']
        stats[st]=stats.get(st,0)+1
        if st=='type_error':
            found.append(json.dumps(p))
        elif st=='other_runtime_error':
            other.append((json.dumps(p),res.get('message')))
    print(stats)
    for f in found[:5]:
        print('TYPE_ERROR:',f)
    for f in other[:5]:
        print('OTHER:',f)
    open('/work/found.json','w').write('\n'.join(found))

